use vstd::prelude::*;  // bring in Verus’s #[requires]/#[ensures] attributes, etc.

/// Return the minimum number of coins and notes (100, 20, 10, 5, 1)
/// needed to make `n`, by the canonical greedy algorithm.
#[requires(n >= 0)]  
#[ensures(|ret: i8| ret == 
    // coins/notes of 100
    n / 100 
    // coins/notes of 20 from the remainder mod 100
    + (n % 100) / 20
    // coins/notes of 10 from the remainder mod 20
    + (n % 20) / 10
    // coins/notes of 5 from the remainder mod 10
    + (n % 10) / 5
    // leftover 1‐units
    + (n % 5)
)]
pub fn solve(n: i8) -> i8 {
    // Compute remainders at each step of the canonical decomposition.
    let rem100 = n % 100;
    let rem20  = rem100 % 20;
    let rem10  = rem20 % 10;
    let rem5   = rem10 % 5;

    // Sum the quotients for each denomination and the leftover ones.
    (n / 100)     // number of 100‐value notes
    + (rem100 / 20)  // number of 20‐value notes
    + (rem20 / 10)   // number of 10‐value notes
    + (rem10 / 5)    // number of 5‐value coins
    + rem5           // number of 1‐value coins
}

